import 'package:flutter/material.dart'; import '../services/settings_service.dart';
class SettingsScreen extends StatefulWidget{const SettingsScreen({super.key});@override State<SettingsScreen> createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{final pin=TextEditingController();String msg='';@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('SYSTEM SETTINGS')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('SECURITY PROTOCOL',style:TextStyle(color:Color(0xFF65E8FF),letterSpacing:2)),const SizedBox(height:18),TextField(controller:pin,obscureText:true,maxLength:8,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'PIN من 4 إلى 8 أرقام')),FilledButton(onPressed:()async{if(pin.text.length<4||int.tryParse(pin.text)==null){setState(()=>msg='أدخل رمزاً رقمياً صحيحاً');return;}await SettingsService.setPin(pin.text);pin.clear();setState(()=>msg='تم تفعيل قفل التطبيق');},child:const Text('تفعيل / تغيير PIN')),if(SettingsService.pinEnabled)TextButton(onPressed:()async{await SettingsService.removePin();setState(()=>msg='تم تعطيل القفل');},child:const Text('إزالة القفل')),Text(msg,style:const TextStyle(color:Color(0xFF65E8FF))),const Divider(height:40),const ListTile(leading:Icon(Icons.notifications_active),title:Text('Adaptive Alerts'),subtitle:Text('تختلف أولوية الإشعار والاهتزاز حسب مستوى المهمة')),const ListTile(leading:Icon(Icons.storage),title:Text('Local Storage'),subtitle:Text('تخزين محلي دون حساب أو خادم'))]));}
